/* From Uiverse.io by kennyotsu - Tags: simple, material design, alert, notification, card */
.__UIV_SCOPE__ .notifications-container {
  width: 320px;
  height: auto;
  font-size: 0.875rem;
  line-height: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.__UIV_SCOPE__ .flex {
  display: flex;
}

.__UIV_SCOPE__ .flex-shrink-0 {
  flex-shrink: 0;
}

.__UIV_SCOPE__ .error-alert {
  border-radius: 0.375rem;
  padding: 1rem;
  background-color: rgb(254 242 242);
}

.__UIV_SCOPE__ .error-svg {
  color: #F87171;
  width: 1.25rem;
  height: 1.25rem;
}

.__UIV_SCOPE__ .error-prompt-heading {
  color: #991B1B;
  font-size: 0.875rem;
  line-height: 1.25rem;
  font-weight: bold;
}

.__UIV_SCOPE__ .error-prompt-container {
  display: flex;
  flex-direction: column;
  margin-left: 1.25rem;
}

.__UIV_SCOPE__ .error-prompt-wrap {
  margin-top: 0.5rem;
  color: #B91C1C;
  font-size: 0.875rem;
  line-height: 1.25rem;
}

.__UIV_SCOPE__ .error-prompt-list {
  padding-left: 1.25rem;
  margin-top: 0.25rem;
  list-style-type: disc;
}
